/**
 * Sección de mostrar el icono del logo en la pantalla de inicio de GLPI
 */
function plugin_logocamy_display_central(): void{
    echo 
    "<div class='contenedor'>
    <a class='boton' href='https://www.yumbo.gov.co/publicaciones/99/secretaria-de-educacion/' target='_blank' rel='noopener noreferrer'>
        <img src='data:image/png;base64,' alt='Logo'>
        <span>Ir a secretaría</span>
    </a>
    </div>
";
}

/**
 * Plugin install process
 */
function plugin_logocamy_install(): bool
{
    return true;
}

/**
 * Plugin uninstall process
 */
function plugin_logocamy_uninstall(): bool
{
    return true;
}
